class Todo:
    def __init__(self):
        self.items = []

    def add(self, text):
        self.items.append([text, False])

    def done(self, index):
        self.items[index][1] = True

    def pending(self):
        return [text for text, ok in self.items if not ok]


todo = Todo()
for _ in range(int(input())):
    command, arg = input().split(" ", 1)
    if command == "add":
        todo.add(arg)
    else:
        todo.done(int(arg))
rest = todo.pending()
print("\n".join(rest) if rest else "все дела сделаны")

